def median(xs: list[float]) -> float:
    """Median of a non-empty list. For even length, the mean of the two middle values."""
    sorted_xs = sorted(xs)
    n = len(sorted_xs)
    mid = n // 2

    if n % 2 == 1:
        return sorted_xs[mid]
    else:
        return (sorted_xs[mid - 1] + sorted_xs[mid]) / 2

def run_length(s: str) -> str:
    if not s:
        return ""

    result = []
    current_char = s[0]
    count = 1

    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            result.append(f"{current_char}{count}")
            current_char = char
            count = 1

    result.append(f"{current_char}{count}")
    return "".join(result)

