def word_count(s: str) -> dict[str, int]:
    """Count lowercase words split on whitespace."""
    if not s.strip():
        return {}

    words = s.split()
    word_counts = {}

    for word in words:
        lower_word = word.lower()
        word_counts[lower_word] = word_counts.get(lower_word, 0) + 1

    return word_counts
